import sys

def lines(p):
    return [l.rstrip('\n') for l in open(p) if l.strip() and not l.startswith('#')]

def csum(s):
    return sum(ord(c) for c in s) & 0xFFFF

for path in ['/app/data/sample_stall_journal.psv', '/app/data/stall_journal.psv', '/app/data/calibration_stall_journal.psv']:
    print('==', path)
    segs = []
    for l in lines(path):
        if l.startswith('@|'):
            f = l.split('|')
            segs.append({'hdr': f, 'body': []})
        else:
            segs[-1]['body'].append(l.split('|'))
    bad = 0
    tot = 0
    for s in segs:
        _, sid, worker, cnt, origin, flags, key, chk = s['hdr']
        flags = int(flags, 16)
        n = len(s['body'])
        assert n == int(cnt) or (flags & 0x008), (sid, cnt, n)
        lsum = 0
        for b in s['body']:
            tot += 1
            c = csum('|'.join(b[:9]))
            lsum += int(b[9], 16)
            if c != int(b[9], 16):
                bad += 1
        if lsum & 0xFFFF != int(chk, 16):
            print('  segchk mismatch', sid)
    print('  segs', len(segs), 'body', tot, 'badline', bad)
    flagset = set(int(s['hdr'][5], 16) for s in segs)
    print('  flags', sorted(hex(f) for f in flagset))

