import json, sys
sys.path.insert(0, '/app/scratch')
from wire import read_journal, stride_order, unzig, F_PAD, F_STRIDE, F_WAITDELTA

CTRL = json.load(open('/app/data/control-slice-figures.json'))
segs = read_journal('/app/data/calibration_stall_journal.psv')
TARGET = CTRL['CTRL-B']


def run(stride, bias, span, chain_order, inv, perm_over):
    """perm_over: 'all' or 'true'"""
    tot = 0
    cnt = 0
    for s in segs:
        flags = s['flags']
        n = len(s['body'])
        npad = (s['key'] % bias) if flags & F_PAD else 0
        ntrue = n - npad
        m = n if perm_over == 'all' else ntrue
        if flags & F_STRIDE:
            pos = stride_order(m, stride)
            if inv:
                q = [0] * m
                for i, p in enumerate(pos):
                    q[p] = i
                pos = q
        else:
            pos = list(range(m))
        w = {}
        if flags & F_WAITDELTA:
            seq = pos if chain_order == 'logical' else list(range(m))
            prev = None
            for i in seq:
                v = int(s['body'][i][1])
                w[i] = v if prev is None else prev + unzig(v)
                prev = w[i]
        else:
            for i in range(m):
                w[i] = int(s['body'][i][1])
        keep = [pos[i] for i in range(ntrue)] if m == n else list(range(ntrue))
        tot += sum(w[i] for i in keep)
        cnt += len(keep)
    return tot, cnt


best = []
for bias in (2, 3, 4, 5, 6):
    for st in (3, 5, 7, 9, 11, 13):
        for co in ('logical', 'physical'):
            for inv in (False, True):
                for po in ('all', 'true'):
                    t, c = run(st, bias, None, co, inv, po)
                    if c == CTRL['CTRL-A'] and t == TARGET:
                        print('HIT', bias, st, co, inv, po, t, c)
                        best.append((bias, st, co, inv, po))
print('hits', len(best))

